// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/v1/action-approvals", wrapper.ListActionApprovals)
	m.HandleFunc("GET "+options.BaseURL+"/v1/action-approvals/watch", wrapper.WatchActionApprovals)
	m.HandleFunc("POST "+options.BaseURL+"/v1/action-approvals/{approval_id}/decide", wrapper.DecideActionApproval)
	m.HandleFunc("GET "+options.BaseURL+"/v1/actions", wrapper.ListActions)
	m.HandleFunc("POST "+options.BaseURL+"/v1/actions/install", wrapper.InstallAction)
	m.HandleFunc("GET "+options.BaseURL+"/v1/actions/{name}", wrapper.GetAction)
	m.HandleFunc("POST "+options.BaseURL+"/v1/actions/{name}/run", wrapper.RunAction)
	m.HandleFunc("GET "+options.BaseURL+"/v1/analytics/summary", wrapper.GetAnalyticsSummary)
	m.HandleFunc("GET "+options.BaseURL+"/v1/approvals", wrapper.ListApprovals)
	m.HandleFunc("GET "+options.BaseURL+"/v1/approvals/{approval_id}", wrapper.GetApproval)
	m.HandleFunc("POST "+options.BaseURL+"/v1/approvals/{approval_id}/approve", wrapper.ApproveRequest)
	m.HandleFunc("POST "+options.BaseURL+"/v1/approvals/{approval_id}/deny", wrapper.DenyRequest)
	m.HandleFunc("POST "+options.BaseURL+"/v1/approvals/{approval_id}/modify", wrapper.ModifyRequest)
	m.HandleFunc("GET "+options.BaseURL+"/v1/bindings", wrapper.ListBindings)
	m.HandleFunc("POST "+options.BaseURL+"/v1/bindings/setup", wrapper.SetupBindings)
	m.HandleFunc("POST "+options.BaseURL+"/v1/bindings/setup/oauth2/finish", wrapper.FinishOAuth2Binding)
	m.HandleFunc("POST "+options.BaseURL+"/v1/bindings/setup/oauth2/init", wrapper.InitOAuth2Binding)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/bindings/{name}", wrapper.RevokeBinding)
	m.HandleFunc("GET "+options.BaseURL+"/v1/bindings/{name}", wrapper.GetBinding)
	m.HandleFunc("POST "+options.BaseURL+"/v1/bindings/{name}/rebind", wrapper.RebindBinding)
	m.HandleFunc("POST "+options.BaseURL+"/v1/chat/completions", wrapper.PostChatCompletions)
	m.HandleFunc("GET "+options.BaseURL+"/v1/connect/{provider}", wrapper.ConnectAccount)
	m.HandleFunc("GET "+options.BaseURL+"/v1/connect/{provider}/callback", wrapper.ConnectAccountCallback)
	m.HandleFunc("GET "+options.BaseURL+"/v1/connected-accounts", wrapper.ListConnectedAccounts)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/connected-accounts/{id}", wrapper.DeleteConnectedAccount)
	m.HandleFunc("GET "+options.BaseURL+"/v1/connected-accounts/{id}", wrapper.GetConnectedAccount)
	m.HandleFunc("GET "+options.BaseURL+"/v1/connectors", wrapper.ListConnectors)
	m.HandleFunc("POST "+options.BaseURL+"/v1/connectors", wrapper.CreateConnector)
	m.HandleFunc("POST "+options.BaseURL+"/v1/connectors/install", wrapper.InstallConnector)
	m.HandleFunc("GET "+options.BaseURL+"/v1/connectors/{connector_id}", wrapper.GetConnector)
	m.HandleFunc("PATCH "+options.BaseURL+"/v1/connectors/{connector_id}", wrapper.UpdateConnector)
	m.HandleFunc("GET "+options.BaseURL+"/v1/credentials", wrapper.ListCredentials)
	m.HandleFunc("POST "+options.BaseURL+"/v1/credentials", wrapper.CreateCredential)
	m.HandleFunc("GET "+options.BaseURL+"/v1/enterprises/me", wrapper.GetCurrentEnterprise)
	m.HandleFunc("PATCH "+options.BaseURL+"/v1/enterprises/me", wrapper.UpdateCurrentEnterprise)
	m.HandleFunc("GET "+options.BaseURL+"/v1/execution-grants/{grant_id}", wrapper.GetExecutionGrant)
	m.HandleFunc("POST "+options.BaseURL+"/v1/executions/run", wrapper.RunExecution)
	m.HandleFunc("GET "+options.BaseURL+"/v1/executions/{execution_id}", wrapper.GetExecution)
	m.HandleFunc("POST "+options.BaseURL+"/v1/executions/{execution_id}/callback", wrapper.ExecutionCallback)
	m.HandleFunc("GET "+options.BaseURL+"/v1/funding-sources", wrapper.ListFundingSources)
	m.HandleFunc("POST "+options.BaseURL+"/v1/funding-sources", wrapper.CreateFundingSource)
	m.HandleFunc("GET "+options.BaseURL+"/v1/health", wrapper.GetHealth)
	m.HandleFunc("GET "+options.BaseURL+"/v1/intents", wrapper.ListIntents)
	m.HandleFunc("POST "+options.BaseURL+"/v1/intents", wrapper.CreateIntent)
	m.HandleFunc("GET "+options.BaseURL+"/v1/intents/{intent_id}", wrapper.GetIntent)
	m.HandleFunc("POST "+options.BaseURL+"/v1/intents/{intent_id}/evidence", wrapper.AppendIntentEvidence)
	m.HandleFunc("POST "+options.BaseURL+"/v1/messages", wrapper.PostMessages)
	m.HandleFunc("GET "+options.BaseURL+"/v1/policies", wrapper.ListPolicies)
	m.HandleFunc("POST "+options.BaseURL+"/v1/policies", wrapper.CreatePolicy)
	m.HandleFunc("POST "+options.BaseURL+"/v1/policies/simulate", wrapper.SimulatePolicy)
	m.HandleFunc("GET "+options.BaseURL+"/v1/policies/{policy_id}", wrapper.GetPolicy)
	m.HandleFunc("PATCH "+options.BaseURL+"/v1/policies/{policy_id}", wrapper.UpdatePolicy)
	m.HandleFunc("GET "+options.BaseURL+"/v1/status", wrapper.GetStatus)
	m.HandleFunc("POST "+options.BaseURL+"/v1/tee/attestation", wrapper.InitiateAttestation)
	m.HandleFunc("GET "+options.BaseURL+"/v1/tee/jwks", wrapper.GetTeeJwks)
	m.HandleFunc("POST "+options.BaseURL+"/v1/tee/session", wrapper.EstablishTeeSession)
	m.HandleFunc("GET "+options.BaseURL+"/v1/tee/status", wrapper.GetTeeStatus)
	m.HandleFunc("GET "+options.BaseURL+"/v1/traces", wrapper.ListTraces)
	m.HandleFunc("GET "+options.BaseURL+"/v1/users/me", wrapper.GetCurrentUser)
	m.HandleFunc("PATCH "+options.BaseURL+"/v1/users/me", wrapper.UpdateCurrentUser)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/users/me/auth-providers/{provider}", wrapper.DisconnectAuthProvider)
	m.HandleFunc("POST "+options.BaseURL+"/v1/users/me/passphrase", wrapper.SetPassphrase)
	m.HandleFunc("POST "+options.BaseURL+"/v1/users/me/passphrase/lock", wrapper.LockVault)
	m.HandleFunc("GET "+options.BaseURL+"/v1/users/me/passphrase/salt", wrapper.GetPassphraseSalt)
	m.HandleFunc("POST "+options.BaseURL+"/v1/users/me/passphrase/unlock", wrapper.UnlockVault)
	m.HandleFunc("GET "+options.BaseURL+"/v1/users/me/passphrase/verification", wrapper.GetPassphraseVerification)
	m.HandleFunc("GET "+options.BaseURL+"/v1/users/me/vault/status", wrapper.GetVaultStatus)

	return m
}

